package main

import (
	"context"
	"fmt"
	"os"

	sdk "dedalus"
	"dedalus/option"
)

func main() {
	client := sdk.NewClient(
		option.WithBearer(os.Getenv("BEARER")),
		option.WithAPIKey(os.Getenv("DEDALUS_API_KEY")),
	)

	stream := client.MachineLifecycle.WatchStatusStreaming(context.Background(), sdk.MachineLifecycleWatchStatusParams{
		MachineID: "machineID",
	})
	defer stream.Close()
	for stream.Next() {
		event := stream.Current()
		fmt.Println(event)
	}
	if err := stream.Err(); err != nil {
		panic(err)
	}
}

